/* 350 mathematics exercises for grade seven, at three regular levels. */
(()=>{for(let topic=0;topic<10;topic++)for(let level=0;level<3;level++)for(let i=0;i<11+(level!==topic%3?1:0);i++){
 const n=i+4;let q,a,steps,hint;
 if(topic===0){hint='Выполни одинаковые преобразования с обеими частями уравнения.';if(level===0){q=`Реши уравнение x + ${n} = ${2*n}.`;a=n;steps=[`Вычтем ${n} из обеих частей.`,`x = ${2*n} − ${n} = ${a}.`]}if(level===1){q=`Реши уравнение 3x − ${2*n} = ${n}.`;a=n;steps=[`3x = ${n} + ${2*n} = ${3*n}.`,`x = ${3*n} : 3 = ${a}.`]}if(level===2){q=`Реши уравнение 5(x − ${n}) = 3x + ${n}.`;a=3*n;steps=[`Раскроем скобки: 5x − ${5*n} = 3x + ${n}.`,`2x = ${6*n}, поэтому x = ${a}.`]} }
 if(topic===1){hint='Используй правила действий со степенями и формулы сокращённого умножения.';if(level===0){q=`Вычисли ${n}².`;a=n*n;steps=[`${n}² = ${n}·${n} = ${a}.`]}if(level===1){q=`Вычисли ${n}² · ${n}³ / ${n}⁴.`;a=n;steps=[`При умножении показатели складываются, при делении вычитаются.`,`${n}^(2+3−4) = ${a}.`]}if(level===2){q=`Вычисли (${n}+1)² − ${n}².`;a=2*n+1;steps=[`По формуле разности квадратов (n+1)²−n² = 2n+1.`,`При n = ${n} получаем ${a}.`]} }
 if(topic===2){hint='Используй сумму углов треугольника и свойства равнобедренного треугольника.';if(level===0){q=`Два угла треугольника равны ${40+n}° и 50°. Найди третий угол в градусах.`;a=90-n;steps=[`Сумма углов треугольника 180°.`,`180 − ${40+n} − 50 = ${a}°.`]}if(level===1){q=`Угол при вершине равнобедренного треугольника равен ${20+2*n}°. Найди угол при основании в градусах.`;a=80-n;steps=[`Углы при основании равны.`,`(180 − ${20+2*n})/2 = ${a}°.`]}if(level===2){q=`Внешний угол треугольника равен ${120-2*n}°. Один из двух внутренних углов, не смежных с ним, равен 30°. Найди второй в градусах.`;a=90-2*n;steps=[`Внешний угол равен сумме двух внутренних несмежных углов.`,`${120-2*n} − 30 = ${a}°.`]} }
 if(topic===3){hint='Сложи уравнения или подставь известную переменную.';if(level===0){q=`Дано x + y = ${3*n} и x = ${n}. Найди y.`;a=2*n;steps=[`Подставим x = ${n}.`,`y = ${3*n} − ${n} = ${a}.`]}if(level===1){q=`Реши систему x + y = ${3*n}, x − y = ${n}. Найди x.`;a=2*n;steps=[`Сложим уравнения: 2x = ${4*n}.`,`x = ${a}.`]}if(level===2){q=`Реши систему 2x + y = ${5*n}, x − y = ${n}. Найди x.`;a=2*n;steps=[`Сложим уравнения: 3x = ${6*n}.`,`x = ${a}; тогда y = ${n}.`]} }
 if(topic===4){hint='Подставь значение аргумента или приравняй значения функций.';if(level===0){q=`Функция задана формулой y = 3x + ${n}. Найди y при x = 2.`;a=n+6;steps=[`Подставим x = 2.`,`y = 3·2 + ${n} = ${a}.`]}if(level===1){q=`При каком x функция y = 2x + ${n} принимает значение ${3*n}?`;a=n;steps=[`Получаем 2x + ${n} = ${3*n}.`,`2x = ${2*n}, x = ${a}.`]}if(level===2){q=`Найди абсциссу точки пересечения прямых y = 2x + ${n} и y = −x + ${4*n}.`;a=n;steps=[`В точке пересечения 2x + ${n} = −x + ${4*n}.`,`3x = ${3*n}, откуда x = ${a}.`]} }
 if(topic===5){hint='Используй свойства смежных углов и параллельных прямых.';if(level===0){q=`Один из двух смежных углов равен ${n+40}°. Найди второй угол в градусах.`;a=140-n;steps=[`Сумма смежных углов равна 180°.`,`180 − ${n+40} = ${a}°.`]}if(level===1){q=`Две параллельные прямые пересечены секущей. Один угол равен ${n+30}°. Найди соответствующий ему угол в градусах.`;a=n+30;steps=[`Соответственные углы при параллельных прямых равны.`,`Искомый угол равен ${a}°.`]}if(level===2){q=`Два смежных угла равны 2x° и (x + ${n})°. Найди x.`;a=(180-n)/3;steps=[`По свойству смежных углов 2x + x + ${n} = 180.`,`3x = ${180-n}, следовательно x = ${180-n}/3.`]} }
 if(topic===6){hint='У равных треугольников соответствующие стороны равны.';if(level===0){q=`Треугольники ABC и DEF равны, причём A соответствует D, B — E, C — F. Если AB = ${n}, найди DE.`;a=n;steps=[`Стороне AB соответствует сторона DE.`,`Соответственные стороны равны: DE = ${a}.`]}if(level===1){q=`Равные треугольники имеют соответствующие стороны ${n}, ${n+2} и ${n+3}. Найди периметр каждого.`;a=3*n+5;steps=[`Периметр — сумма трёх сторон.`,`${n} + ${n+2} + ${n+3} = ${a}.`]}if(level===2){q=`Два равных треугольника имеют общий периметр ${2*(3*n+5)}. Стороны одного равны ${n}, ${n+2} и x. Найди x.`;a=n+3;steps=[`Периметры равных треугольников одинаковы: каждый равен ${3*n+5}.`,`x = ${3*n+5} − ${n} − ${n+2} = ${a}.`]} }
 if(topic===7){hint='Каждая сторона треугольника меньше суммы двух других и больше их разности.';if(level===0){q=`Две стороны треугольника равны ${n} и ${n+2}. Какова наибольшая целая длина третьей стороны?`;a=2*n+1;steps=[`Третья сторона меньше ${n} + ${n+2} = ${2*n+2}.`,`Наибольшее целое значение — ${a}; оно больше разности сторон 2.`]}if(level===1){q=`Две стороны треугольника равны ${n} и ${n+2}. Сколько целых значений может принимать третья сторона?`;a=2*n-1;steps=[`Третья сторона x удовлетворяет 2 < x < ${2*n+2}.`,`Целые значения от 3 до ${2*n+1}; их ${a}.`]}if(level===2){q=`Основание равнобедренного треугольника равно ${2*n}. Какова наименьшая целая длина боковой стороны?`;a=n+1;steps=[`Сумма боковых сторон строго больше основания: 2x > ${2*n}.`,`x > ${n}; наименьшее целое x = ${a}.`]} }
 if(topic===8){hint='Приведи подобные слагаемые или примени формулу разности квадратов.';if(level===0){q=`Найди коэффициент при x после упрощения ${n}x + 3x.`;a=n+3;steps=[`Сложим коэффициенты при x: ${n} + 3 = ${a}.`]}if(level===1){q=`Вычисли (${n}+2)² − ${n}².`;a=4*n+4;steps=[`Разность квадратов: ((n+2)−n)((n+2)+n) = 2(2n+2).`,`При n = ${n} получаем ${a}.`]}if(level===2){q=`Известно x + y = ${n+2} и x − y = ${n}. Найди x² − y².`;a=n*(n+2);steps=[`Разложим: x² − y² = (x−y)(x+y).`,`Подставляем: ${n}·${n+2} = ${a}.`]} }
 if(topic===9){hint='При умножении степеней с одинаковым основанием показатели складываются.';if(level===0){q=`Чему равен показатель степени после упрощения ${n}² · ${n}³?`;a=5;steps=[`Основание одинаковое, поэтому складываем показатели: 2+3 = ${a}.`]}if(level===1){q=`Чему равен показатель степени после упрощения ${n}⁷ / ${n}³?`;a=4;steps=[`При делении степеней с одинаковым ненулевым основанием вычитаем показатели: 7−3 = ${a}.`]}if(level===2){q=`Найди натуральное x, если 2^x · 2³ = 2^${n+3}.`;a=n;steps=[`Слева 2^(x+3). Одинаковые степени двойки имеют равные показатели.`,`x + 3 = ${n+3}, поэтому x = ${a}.`]} }
 tasks.push({id:`grade7-practice-${topic}-${level}-${i}`,domain:'math',grade:7,subject:topicSubjects[`7-${topic}`],topic,topicName:curriculum[7][topic][0],level,title:['Базовая задача','Углублённая задача','Внешкольная задача'][level]+' · '+(i+1),question:q,answer:a,hints:[hint,'Проверь ответ обратным действием или подстановкой.'],steps,review:{plan:hint,verify:steps[steps.length-1],trap:'Проверь, какая величина требуется в ответе.'},challenge:level===2,goal:'Разобраться в решении и проверить ответ'});
}})();
